def add_binary(a, b):
    i, j, carry, res = len(a)-1, len(b)-1, 0, []
    while i>=0 or j>=0 or carry:
        total = carry
        if i>=0:
            total += int(a[i]); i-=1
        if j>=0:
            total += int(b[j]); j-=1
        res.append(str(total%2))
        carry = total//2
    return ''.join(reversed(res))  # returns binary sum as string

