def counting_adc(v_in, v_ref=5.0, bits=3):
    step = v_ref / (2**bits)
    count = 0
    while count * step < v_in and count < 2**bits - 1:
        count += 1
    return count, count+1  # code, cycles (including final compare)
# Example: counting_adc(2.7) -> (5, 6)

module counting_adc(
    input wire clk,
    input wire rst_n,
    input wire [11:0] analog, // scaled integer representation
    output reg [3:0] digital,
    output reg done
);
    reg [3:0] cnt;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 0; digital <= 0; done <= 0;
        end else if (!done) begin
            if (cnt * (12'd4095/4'd15) >= analog) begin
                digital <= cnt; done <= 1;
            end else begin
                cnt <= cnt + 1'b1;
            end
        end
    end
endmodule // simple behavioral model

